-- study_objective  (printed p.1)
update public.fields set verification_status='verified_against_standard', verification_quote='The choice of representative sampling points, frequency of sampling, type of samples taken, etc. is dependent on the objective of the study. In general, the sampling approach for chemical analysis is compatible with the purpose of biotesting. - printed p.1', verification_note='md-verified 2026-09-09 (§3.1 General, printed p.1) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.7. The guideline names the study objective as the governing input (see also §7.6 "The selection of the pH value ... is governed by the objective of the test") but states no obligation to record it; the encoded is_required=true has no mandatory verb behind it - staged.', verified_at=now() where id='83ab9a11-ef46-450a-b243-b154e36fbfc5' and verification_status not in ('verified_against_standard','corrected');

-- biotest_type  (printed p.1)
update public.fields set verification_status='verified_against_standard', verification_quote='Special emphasis is laid on ecotoxicological testing with organisms (''single-species biotests''). Some features addressed in this general guidance apply as well to biodegradation and/or bioaccumulation studies as far as sampling and sample preparations is concerned. Preparation of poorly soluble substances and testing beyond the water-solubility limit is also addressed. | This part of ISO 5667 is not applicable to bacteriological examination of water. Appropriate methods are described in other International Standards. - printed p.1', verification_note='md-verified 2026-09-09 (§1 Scope, printed p.1) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.7. CAVEAT: §1 names toxicity/ecotoxicological, biodegradation and bioaccumulation testing; the fourth enum value "genotoxicity" is sourced from §11.3 (printed p.19), not from §1. The scope prints "and/or", i.e. a single-select widget cannot express the printed conjunction - staged.', verified_at=now() where id='8317a7e8-3693-4b75-8d0e-6a60b86cc412' and verification_status not in ('verified_against_standard','corrected');

-- normative_references_consulted  (printed p.1)
update public.fields set verification_status='verified_against_standard', verification_quote='The following standards contain provisions which, through reference in this text, constitute provisions of this part of ISO 5667. [...] ISO 5667-3 :1994, Water quality - Sampling - Part 3: Guidance on the preservation and handling of samples. | ISO 5667-10 :1992, Water quality - Sampling - Part 10: Guidance on sampling of waste waters. - printed p.1', verification_note='md-verified 2026-09-09 (§2 Normative references, printed p.1) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.7. CAVEAT: the clause is the ISO boilerplate; the only modal it carries about editions is "are encouraged to investigate". Gate CR-002 enforces this at severity=block on that boilerplate - staged as block->warn.', verified_at=now() where id='14663224-b0b7-4387-8680-7bb01d19507d' and verification_status not in ('verified_against_standard','corrected');

-- sampling_point_representative  (printed p.1)
update public.fields set verification_status='verified_against_standard', verification_quote='The choice of representative sampling points, frequency of sampling, type of samples taken, etc. is dependent on the objective of the study. In general, the sampling approach for chemical analysis is compatible with the purpose of biotesting. - printed p.1', verification_note='md-verified 2026-09-09 (§3.1 General, printed p.1) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.7. The clause is descriptive ("is dependent on"); it contains no shall/should obliging a representativeness attestation.', verified_at=now() where id='6bcf35d6-d45a-42ba-ace9-45e34ff82f6a' and verification_status not in ('verified_against_standard','corrected');

-- subsamples_homogenized  (printed p.2)
update public.fields set verification_status='verified_against_standard', verification_quote='If several samples have been taken (e.g. from different locations or at several times) they may be combined to achieve greater representativity. These samples should be thoroughly mixed and, if necessary, divided into subsamples. To obtain subsamples of equal quality, it should be ensured that the bulk sample maintains homogeneity during the subsampling process, e.g. by continuous shaking or stirring. This holds particularly in the case of two-phase mixtures, e.g. waters containing suspended particles, algal suspensions. - printed p.2', verification_note='md-verified 2026-09-09 (§3.1 General, printed p.2) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.8.', verified_at=now() where id='7dc9d434-68c7-489a-ae27-4e3a1774dbba' and verification_status not in ('verified_against_standard','corrected');

-- vessel_material  (printed p.2)
update public.fields set verification_status='verified_against_standard', verification_quote='The material of vessels should be chemically inert, easily cleaned and resistant to heating and freezing. Glassware, polyethene or polytetrafluoroethene (PTFE) vessels are recommended. - printed p.2', verification_note='md-verified 2026-09-09 (§3.2 Samplers/vessels/containers, printed p.2) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.8. Printed modality is "are recommended"; the enum carries an "other" escape, so it does not close the printed list.', verified_at=now() where id='364e24b4-8528-4ef3-8e7e-fd468b257dea' and verification_status not in ('verified_against_standard','corrected');

-- sample_volume  (printed p.2)
update public.fields set verification_status='verified_against_standard', verification_quote='The time required for freezing and thawing should be minimized by reducing the sample volume, i.e. the size of the vessel. In general it is appropriate to use one-litre vessels for freezing. For tests requiring larger volumes, the sample should be divided into vessels holding not more than 10 l. | The total sample volume taken should be sufficient to cover any supplementary or repeated testing. Remaining subsamples stored frozen separately should be saved until the final evaluation has been made. - printed p.2', verification_note='md-verified 2026-09-09 (§3.2 Samplers/vessels/containers, printed p.2) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.8. FINDING: the printed 10 l is a ceiling on the SIZE OF EACH VESSEL, not on the total sample volume; the printed rule for the TOTAL volume is a sufficiency floor with no ceiling at all. The field description ("generally no more than 10 l") and gate CR-005 (sample_volume <= 10) transplant the vessel ceiling onto the total volume - staged.', verified_at=now() where id='a9069940-0fa4-4d79-8275-459da85144f3' and verification_status not in ('verified_against_standard','corrected');

-- container_filling_status  (printed p.2)
update public.fields set verification_status='verified_against_standard', verification_quote='It should be decided whether the containers should be filled completely to the brim or only partially, having an air space, by taking into account the type of sample, the preservation mode and the biotest envisaged. | Sample containers, when freezing is envisaged for preservation, should not be filled completely in order to allow expansion of volume. - printed p.2', verification_note='md-verified 2026-09-09 (§3.3 Filling status of containers, printed p.2) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.8. FINDING: the second sentence is a printed CONDITIONAL rule (freezing envisaged => not completely filled). Gate CR-006 is presence-only (container_filling_status IS NOT NULL) and therefore hides it - staged.', verified_at=now() where id='bbbb0b91-41f2-4f1b-9b40-eb514891a1f2' and verification_status not in ('verified_against_standard','corrected');

-- transport_protected  (printed p.2)
update public.fields set verification_status='verified_against_standard', verification_quote='The samples collected should be protected from breakage, temperature increase and external contamination. Misidentification of samples transported in melting ice should be avoided by using waterproof markers and/or labels. - printed p.2', verification_note='md-verified 2026-09-09 (§4 Transport, printed p.2) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.8.', verified_at=now() where id='ffc25b0c-3ff6-4247-9939-fbf3b8bbeb8f' and verification_status not in ('verified_against_standard','corrected');

-- ambient_storage_time  (printed p.3)
update public.fields set verification_status='verified_against_standard', verification_quote='Samples for biotesting should be processed preferably without delay after collection to avoid changes in the original composition as a result of physical and chemical reactions and/or biological processes. The maximum duration of storage should not exceed 12 h at ambient temperature (maximum 25 °C). The samples should be kept in the dark to prevent algal growth. - printed p.3', verification_note='md-verified 2026-09-09 (§5 Preservation and storage, printed p.3) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.9. FINDING: the printed modal is "should not exceed"; the encoded field description states "shall not exceed" - a modal upgrade with no source. The 12 h boundary itself is correct and inclusive (CR-009: <= 12).', verified_at=now() where id='34deb03d-1fb1-4b78-adf9-272b01d3d4e9' and verification_status not in ('verified_against_standard','corrected');

-- biocidal_preservative_excluded  (printed p.3)
update public.fields set verification_status='verified_against_standard', verification_quote='The use of biocidal preservatives should be excluded for the purpose of biotesting. The addition of highly concentrated acids or bases to stabilize the samples, e.g. HCl or NaOH, is not recommended either. - printed p.3', verification_note='md-verified 2026-09-09 (§5 Preservation and storage, printed p.3) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.9.', verified_at=now() where id='b0964036-794d-4334-beac-2c9c78a5a453' and verification_status not in ('verified_against_standard','corrected');

-- apparatus_material_inert  (printed p.3)
update public.fields set verification_status='verified_against_standard', verification_quote='All materials which come into contact with the test sample should be such that interferences caused by sorption or diffusion of the test material, by elution of foreign matter (e.g. plasticizers) or by growth of organisms, are kept to a minimum. Inert materials are suitable, e.g. glass, PTFE. [...] Pipes made from copper, copper alloy or non-inert plastics are not suitable. - printed p.3', verification_note='md-verified 2026-09-09 (§6.1 Selection of apparatus, printed p.3) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.9.', verified_at=now() where id='75ffdf19-daa7-47a0-8277-f9c1c4c27e39' and verification_status not in ('verified_against_standard','corrected');

-- silanization_done  (printed p.3)
update public.fields set verification_status='verified_against_standard', verification_quote='In order to minimize adsorption of test material on containers, pipes, tubings, glassware or plasticsware can be silanized (siliconized) by soaking or rinsing in a 5 % mass fraction solution of dichlorodimethylsilane in chloroform or heptane. As the organic solvent evaporates, the silane is deposited on the surface, which should be rinsed many times with water or heated at 180 °C for 2 h before use. Silanization should only be used if highly adsorbable substances or water ingredients are to be tested and suitable inert material (e.g. PTFE) is not available. - printed p.3', verification_note='md-verified 2026-09-09 (§6.2 Silanization, printed p.3) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.9. FINDING: the encoded field description INVERTS this clause. The page says silanization should ONLY be used IF highly adsorbable substances are to be tested AND no suitable inert material is available; the description says "not used for highly adsorbable substances or PTFE". Also printed "heptane" (not "n-heptane") and "dichlorodimethylsilane" (not "dimethyldichlorosilane") - staged.', verified_at=now() where id='7adb6e48-1a5c-48ba-9b76-85fe622f6ee5' and verification_status not in ('verified_against_standard','corrected');

-- silanization_concentration  (printed p.3)
update public.fields set verification_status='verified_against_standard', verification_quote='In order to minimize adsorption of test material on containers, pipes, tubings, glassware or plasticsware can be silanized (siliconized) by soaking or rinsing in a 5 % mass fraction solution of dichlorodimethylsilane in chloroform or heptane. - printed p.3', verification_note='md-verified 2026-09-09 (§6.2 Silanization, printed p.3) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.9. FINDING: the page prints a 5 % MASS fraction; the encoded field description states "a volume fraction of 5 %" - an invented specification basis. The value 5 is correct; the basis is not. Also the printed modality is permissive ("can be silanized"), yet gate CR-012 enforces strict equality silanization_concentration == 5 - staged.', verified_at=now() where id='a11b1873-a058-45b7-972c-8049316a25ae' and verification_status not in ('verified_against_standard','corrected');

-- storage_temperature  (printed p.3)
update public.fields set verification_status='verified_against_standard', verification_quote='The maximum duration of storage should not exceed 12 h at ambient temperature (maximum 25 °C). | The most common and recommended way of preserving waste water samples is to cool to between 0 °C and 5 °C. When cooled to this range and stored in the dark, most samples are normally stable for up to 24 h (see ISO 5667-10). | Deep freezing below −18 °C in accordance with ISO 5667-10 allows in general an increase in conservation. A few weeks up to 2 months, depending on the stability of samples, are generally the maximum storage periods. - printed p.3', verification_note='md-verified 2026-09-09 (§5 Preservation and storage, printed p.3) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.9. FINDING: the page prints THREE disjoint regimes (ambient <= 25 °C for <= 12 h; cooled 0 °C to 5 °C for up to 24 h; deep-frozen BELOW −18 °C). −18 °C is a printed CEILING for deep freezing, not a floor. Gate CR-008 encodes a single band storage_temperature >= -18 AND <= 25, which inverts that direction: a sample correctly deep-frozen at −25 °C FAILS the gate, while a physically meaningless "storage at 15 °C" passes. Signed-quantity-vs-one-sided-limit defect - staged. The 0-5 °C range and the 24 h cooled-storage figure are not encoded anywhere.', verified_at=now() where id='fd9711d0-5f14-4b6c-9351-d09ce3b72137' and verification_status not in ('verified_against_standard','corrected');

-- preparation_step  (printed p.5)
update public.fields set verification_status='verified_against_standard', verification_quote='The test sample is made from the sample by means of various preparatory steps specific to the sample and the test, e.g. by dissolving, homogenizing, sedimenting, filtering, neutralizing or aerating. Dilution water is added to prepare a series of defined dilutions. Following addition of the test-specific nutrient medium, the test medium (including test sample) is obtained. - printed p.5', verification_note='md-verified 2026-09-09 (§7.1 General (Figure 1), printed p.5) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.11. CAVEAT: the printed list is introduced by "e.g." (an open list) and the steps are SEQUENTIAL - a sample is dissolved AND homogenized AND filtered. The encoding is a closed single-select enum of six values - staged.', verified_at=now() where id='9660faa1-930c-40c0-9650-f8a930a97474' and verification_status not in ('verified_against_standard','corrected');

-- thawing_temperature  (printed p.5)
update public.fields set verification_status='verified_against_standard', verification_quote='Samples stored frozen should be thawed immediately before use. Running water or a warm water bath at a temperature not exceeding 25 °C, together with gentle shaking, are recommended to avoid local overheating. | Complete thawing of the samples before use is essential, as the freezing process can have the effect of concentrating some components in the inner part of the sample which freezes last. - printed p.5', verification_note='md-verified 2026-09-09 (§7.2 Thawing, printed p.5) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.11. Gate CR-014 (thawing_temperature <= 25) matches the printed "not exceeding 25 °C" inclusively - correct.', verified_at=now() where id='9db58735-7973-446c-979d-c4124efdf658' and verification_status not in ('verified_against_standard','corrected');

-- homogenization_method  (printed p.5)
update public.fields set verification_status='verified_against_standard', verification_quote='An even distribution of all soluble and particulate components should be ensured. Gentle agitation, vigorous shaking, ultrasonic treatment or high-speed mechanical dispersion may be applied, depending on the nature of the samples. During this treatment step, attention should be given to the potential loss of volatile ingredients. - printed p.5', verification_note='md-verified 2026-09-09 (§7.3 Homogenization, printed p.5) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.11.', verified_at=now() where id='42c7ae1f-7eb3-4921-93a0-c851fa4b6856' and verification_status not in ('verified_against_standard','corrected');

-- membrane_pore_size  (printed p.5)
update public.fields set verification_status='verified_against_standard', verification_quote='Available sterilization methods, such as thermal or UV-treatment or membrane filtration (0,2 µm), all involve a high risk of side effects. Glass-fibre filtration is preferable when filtering is necessary. - printed p.5', verification_note='md-verified 2026-09-09 (§7.4 Separation of soluble and particulate matter, printed p.5) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.11. FINDING: 0,2 µm is printed as a POINT value inside a parenthetical example of sterilization methods (and again in §7.7.3.2, printed p.7, as "a membrane filter, pore size 0,2 µm"). It is nowhere printed as a maximum. Gate CR-015 enforces membrane_pore_size <= 0,2, i.e. a number lifted from an example and turned into a limit - staged.', verified_at=now() where id='185cd2ae-b3b2-4aaf-aabe-921957d6bbd8' and verification_status not in ('verified_against_standard','corrected');

-- coarse_filter_size  (printed p.5)
update public.fields set verification_status='verified_against_standard', verification_quote='When carrying out tests in the presence of particles causing severe problems, it is recommended that the sample be allowed to settle for 30 min to 2 h or a coarse filtration (>50 µm) is carried out, thus removing only gross particles. The separated particle mass may be examined separately. - printed p.5', verification_note='md-verified 2026-09-09 (§7.4 Separation of soluble and particulate matter, printed p.5) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.11. The printed >50 µm threshold carries no gate; it is a recommendation, so no gate is owed.', verified_at=now() where id='dd50f3cb-4045-4bc8-975a-8c330e99f560' and verification_status not in ('verified_against_standard','corrected');

-- centrifugation_force  (printed p.5)
update public.fields set verification_status='verified_against_standard', verification_quote='Centrifugation, e.g. 10 min at 4500 g ± 1500 g, is, in general, preferable to filtration. - printed p.5', verification_note='md-verified 2026-09-09 (§7.4 Separation of soluble and particulate matter, printed p.5) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.11. The rendered page prints "4500 g ± 1500 g" (the OCR read the ± as a plain "+"). Gate CR-016 (3000..6000) is the arithmetically correct two-sided expansion of that tolerance, so this row is NOT a one-sided-encoding defect. It is however an "e.g." example enforced as a band, and the printed 10 min duration is not encoded.', verified_at=now() where id='20a61af8-5e00-4173-8fcc-b0df3ab9976d' and verification_status not in ('verified_against_standard','corrected');

-- settlement_time  (printed p.5)
update public.fields set verification_status='verified_against_standard', verification_quote='When carrying out tests in the presence of particles causing severe problems, it is recommended that the sample be allowed to settle for 30 min to 2 h or a coarse filtration (>50 µm) is carried out, thus removing only gross particles. - printed p.5', verification_note='md-verified 2026-09-09 (§7.4 Separation of soluble and particulate matter, printed p.5) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.11.', verified_at=now() where id='107f0547-c8fd-45e6-9a4e-cb4c5908893a' and verification_status not in ('verified_against_standard','corrected');

-- ph_adjustment_value  (printed p.6)
update public.fields set verification_status='verified_against_standard', verification_quote='The selection of the pH value to which the sample is to be adjusted is governed by the objective of the test: | adjustment to the pH of the receiving water will produce results more representative of the effect of toxicants once in the environment; | adjustment to a defined pH between 6 and 9 (which is usually tolerable for aquatic biota) will permit the expression of ionizable toxicants that would otherwise be masked by pH conditions outside this range. | Neutralization should be omitted if the effect of the pH is to be reflected in the test result - printed p.6', verification_note='md-verified 2026-09-09 (§7.6 pH adjustment, printed p.6) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.12. FINDING: pH 6..9 is ONE OF TWO printed alternatives, the other being the pH of the receiving water; and §7.6 further says neutralization should be OMITTED when the pH effect is to be reflected. Gate CR-017 enforces ph_adjustment_value >= 6 AND <= 9 unconditionally, so a legitimate adjustment to a receiving water at pH 5,4 fails. Conditional obligation enforced unconditionally / missing scope predicate - staged.', verified_at=now() where id='e4281f85-4c29-4efa-a408-9300e0a5ccbe' and verification_status not in ('verified_against_standard','corrected');

-- solubility  (printed p.7)
update public.fields set verification_status='verified_against_standard', verification_quote='Substances with a solubility in water of less than approximately 100 mg/l should be considered as sparingly soluble. When examining poorly soluble substances, ensure that no undissolved matter remains as sediment, as floating particles or in dispersed form. - printed p.7', verification_note='md-verified 2026-09-09 (§7.7.3.1 General, printed p.7) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.13.', verified_at=now() where id='52f9674a-0acf-440a-bbdd-fc554646ae28' and verification_status not in ('verified_against_standard','corrected');

-- solubilizing_aid  (printed p.8)
update public.fields set verification_status='verified_against_standard', verification_quote='There is a variety of mechanical and chemical means to reach the saturation concentration. It should be borne in mind, however, that preference should be given to mechanical aids for preparing saturated solutions. Recourse should only be made to chemical aids (acids, bases, solvents) in exceptional cases. | Aids which can be used to reach the saturation concentration are: a) Sonication/high speed grinder [...] b) Temperature increase [...] c) Use of acids/bases with ensuing neutralization [...] d) Dissolution of the substance in a volatile, nonaqueous miscible solvent [...] e) Dissolution of the substance in a water-miscible, nontoxic solvent [...] f) Sorption of the substance on to an inert carrier. - printed p.8', verification_note='md-verified 2026-09-09 (§7.7.3.2 Testing in the water solubility range, printed p.8) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.14. CAVEAT: the enum merges §7.7.3.2 a)-f) (testing WITHIN the solubility range) with §7.7.3.3 b)-d) (testing ABOVE the solubility limit) into one single-select, and the printed methods are combinable (§7.7.3.3 d), printed p.9: the substance is mixed with an emulsifying agent AND a volatile solvent). Single-select over a printed conjunction - staged. The printed solubilizer ceiling "< 0,1 g/l" (§7.7.3.2 e), printed p.8) has no field and no gate.', verified_at=now() where id='da2b08c9-45f6-47cf-9c9d-c5887e1642e2' and verification_status not in ('verified_against_standard','corrected');

-- emulsifier_concentration  (printed p.9)
update public.fields set verification_status='verified_against_standard', verification_quote='Emulsifying agents in the concentration used (≤100 mg/l) should be non-toxic and stable throughout the test period. - printed p.9', verification_note='md-verified 2026-09-09 (§7.7.3.3 d) Dispersion of the substance with an emulsifying agent, printed p.9) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.15. BOUNDARY CHECKED ON THE IMAGE: the rendered page prints "≤100 mg/l" (an underscored less-than glyph). The OCR transcript reads it as a plain "<100 mg/l". The encoding (field description "<=100 mg/l", gate CR-018 emulsifier_concentration <= 100) follows the PAGE and is therefore CORRECT; the OCR is what is wrong. This quote will score low against the OCR transcript by design - it was not adjusted to match the OCR.', verified_at=now() where id='ccc5a1ee-5d6d-4085-bdf7-c5f239d9e54c' and verification_status not in ('verified_against_standard','corrected');

-- aeration_provided  (printed p.10)
update public.fields set verification_status='verified_against_standard', verification_quote='The oxygen demand of test animals and heterotrophic microorganisms should be accounted for, e.g. by continuous or intermittent aeration. In special cases, e.g. waste waters with an extremely high biochemical oxygen demand (BOD), it is necessary to supply pure oxygen instead of air. Supersaturation (with respect to air) should be avoided. Problems of stripping of volatiles and losses of substances by foaming can be avoided by special methods (see 10.1.3). - printed p.10', verification_note='md-verified 2026-09-09 (§8.1 Aeration, printed p.10) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.16.', verified_at=now() where id='be1006d1-87e8-40f1-8c64-4bcdb2b9b295' and verification_status not in ('verified_against_standard','corrected');

-- ph_controlled_during_test  (printed p.10)
update public.fields set verification_status='verified_against_standard', verification_quote='In certain circumstances (e.g. due to aeration) the pH will drift during the test even if the sample has been neutralized previously. The adjustment and control of the pH during the test should be decided according to the cause of pH drift and the objective of the test. Abiotic drift of pH can be distinguished by means of a batch without organisms. | If, however, the change in pH during the test is an effect of fundamental vital processes such as photosynthesis in algal growth, which is necessarily accompanied by CO2 consumption, it is reasonable not to adjust pH. - printed p.10', verification_note='md-verified 2026-09-09 (§8.3 pH adjustment and control, printed p.10-11) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.16 and 17. FINDING: the standard explicitly leaves pH control to a case-by-case decision and names a case in which it is "reasonable NOT to adjust pH". Gate CR-019 requires ph_controlled_during_test == True unconditionally, contradicting the printed permission - staged. (CR-019 also uses the literal "True" while sibling gates use "true"; casing consistency is a parser risk flagged in the staged file.)', verified_at=now() where id='0fe6c729-bfd5-42d6-aa0a-5981125466bf' and verification_status not in ('verified_against_standard','corrected');

-- dilution_water_type  (printed p.11)
update public.fields set verification_status='verified_against_standard', verification_quote='For physiological reasons, biological tests using aquatic organisms cannot be carried out using deionized water as the medium. Depending on the nature of the analysis, chlorine-free tapwater, synthetic fresh water or sea water (possibly with nutrient additives), ground or surface water shall be used. [...] For some tests with marine organisms, the use of natural sea water is essential. - printed p.11', verification_note='md-verified 2026-09-09 (§9.1 Preparation of dilutions, printed p.11) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.17. FINDING: this is one of only THREE "shall" statements in the whole document, and it permits FIVE media - chlorine-free tapwater, synthetic fresh water, sea water, ground water, surface water. The encoded enum offers only three and omits ground water and surface water, with no "other" escape; gate CR-020 is severity=block over that truncated enum, so it rejects two media the standard expressly permits. Under-inclusive enum closing a printed list - staged.', verified_at=now() where id='1a791638-3d22-469f-8060-8c9a0d40eabc' and verification_status not in ('verified_against_standard','corrected');

-- dilution_series_type  (printed p.12)
update public.fields set verification_status='verified_against_standard', verification_quote='The water specified in the appropriate standard is used as the dilution water. Usually, progressive concentration levels in geometric series are used. | A dilution series is unnecessary when it is only desired to ascertain whether a given concentration or dilution level exhibits an effect (limit test). | It is expedient first in a preliminary range-finding test with fewer test organisms to determine the approximate range of effective concentrations, and only then to conduct the main test. - printed p.12', verification_note='md-verified 2026-09-09 (§9.1, §9.2 Range-finding and limit tests, printed p.12) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.18.', verified_at=now() where id='d33904e3-676a-4a9f-ab2a-275f5af96052' and verification_status not in ('verified_against_standard','corrected');

-- reference_substance  (printed p.12)
update public.fields set verification_status='verified_against_standard', verification_quote='In order to identify possible interferences in the course of the test and to exclude unsuitable test organisms, it is recommended that a substance of known effect (reference substance) is tested at regular intervals. [...] Often-used reference substances in toxicity tests are e.g. sodium dichromate, 3,5-dichlorophenol. - printed p.12', verification_note='md-verified 2026-09-09 (§9.4 Control and reference batches, printed p.12) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.18. CAVEAT: the printed list is introduced by "e.g." and is therefore OPEN; the encoded enum closes it at exactly the two named substances with no "other" value - staged.', verified_at=now() where id='386a421f-902a-4104-9b44-22bbe5f04597' and verification_status not in ('verified_against_standard','corrected');

-- replicate_count  (printed p.13)
update public.fields set verification_status='verified_against_standard', verification_quote='It is generally recommended that the number of control batches should be at least twice that of replicates per concentration/dilution level or increased by √p, where p is the number of test concentrations. | Two replicates per concentration level are the minimum. - printed p.13', verification_note='md-verified 2026-09-09 (§9.5.2, §9.5.3, printed p.13) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.19. Gate CR-022 (replicate_count >= 2) matches the printed minimum exactly. CAVEAT: the FIRST printed rule - control batches at least twice the replicates per level, or increased by √p - has no field and no gate at all; there is no control_batch_count field.', verified_at=now() where id='03e7c376-6082-4469-acc6-89286a73ef4f' and verification_status not in ('verified_against_standard','corrected');

-- threshold_concentration_method  (printed p.13)
update public.fields set verification_status='verified_against_standard', verification_quote='In contrast to limit tests (see 9.2), threshold concentrations (NOEC/LOEC, see 12.3.1) are determined by an analysis of variance (ANOVA) (e.g. Dunnett''s test) to recognize whether a specific concentration delivers a significant effect. - printed p.13', verification_note='md-verified 2026-09-09 (§9.5.2 Threshold concentrations (NOEC/LOEC), printed p.13) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.19. CAVEAT: §12.3.4.1 (printed p.22) additionally names FOEC ("First/Lowest Observed Effect Concentration"), which the two-value enum omits.', verified_at=now() where id='f310c94b-3757-4ad3-a1eb-84e7ad63ae42' and verification_status not in ('verified_against_standard','corrected');

-- response_variable_type  (printed p.13)
update public.fields set verification_status='verified_against_standard', verification_quote='When determining the concentration/response relationship, the type of endpoint data, i.e. whether quantal (qualitative) or metric (quantitative) variables are determined, is of decisive importance for the test design. | The mortality (or immobility) of test organisms determined in the acute test is a typical quantal variable. | In contrast, metric variables show continuous increments, i.e. a response gradient. Typical metric variables are, e.g., body length or biomass, metabolic rates, oxygen production or consumption rates or enzymatic transformation rates. - printed p.13', verification_note='md-verified 2026-09-09 (§9.5.3 Concentration/response relationship, printed p.13) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.19.', verified_at=now() where id='700e7bbc-8e1b-46a7-b477-947950b00cd6' and verification_status not in ('verified_against_standard','corrected');

-- removable_ingredient_loss  (printed p.13)
update public.fields set verification_status='verified_against_standard', verification_quote='Components of a water sample can be lost from the test system for various reasons: evaporation of volatile substances; biodegradation; abiotic degradation (e.g. hydrolysis, photolysis); sorption to or in vessel materials, particularly in the case of hydrophobic ingredients; foaming of surface-active agents; precipitation; flocculation. - printed p.13', verification_note='md-verified 2026-09-09 (§10.1.1 General, printed p.13) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.19. CAVEAT: the seven printed loss paths can occur together (§10.1.6, printed p.15, describes degradation running alongside sorption). The encoding is a single-select enum - single-select over a printed conjunction - staged.', verified_at=now() where id='083f3135-3cae-4706-b68c-2b68152a32bc' and verification_status not in ('verified_against_standard','corrected');

-- adsorption_equilibration_time  (printed p.14)
update public.fields set verification_status='verified_against_standard', verification_quote='Hydrophobic substances can be adsorbed to vessel walls and then - especially at low concentrations - are no longer fully bioavailable. In order to prevent large losses of substance, it is recommended that the vessels be incubated for at least 30 min with the sample at the envisaged concentration prior to the test, the sample then be discarded, and the vessel subsequently filled with fresh sample in order to prepare the test batch. - printed p.14', verification_note='md-verified 2026-09-09 (§10.1.4 Adsorption, printed p.14) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.20. Gate CR-023 (adsorption_equilibration_time >= 30) matches the printed "at least 30 min" inclusively - correct.', verified_at=now() where id='cce40788-7f3f-4d0f-9c38-ebad10ccba91' and verification_status not in ('verified_against_standard','corrected');

-- test_system_mode  (printed p.15)
update public.fields set verification_status='verified_against_standard', verification_quote='It is often difficult to prevent biodegradation in static test systems, as the test organisms such as fish and other test organisms cannot be separated from their accompanying bacteria. [...] In certain cases, flow-through systems may be used. | When using flow-through or semistatic test systems, the effect of the undecomposed sample can be examined more easily. - printed p.15', verification_note='md-verified 2026-09-09 (§10.1.6 Degradation, §10.1.7 Hydrolysis, printed p.15) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.21.', verified_at=now() where id='f8ba1635-724a-42a4-a737-afc32ccc7433' and verification_status not in ('verified_against_standard','corrected');

-- colour_turbidity_correction  (printed p.15)
update public.fields set verification_status='verified_against_standard', verification_quote='In some biological tests, endpoint determination is based on a spectrometric measurement (photometry, fluorometry). In the case of highly coloured or turbid samples, the inhibiting effect produced cannot be determined reliably. The following steps may be taken to overcome this situation: [...] | In the algal test, coloured and turbid substances can directly impede cell growth as a result of light attenuation; this should not to be mistaken for toxic effects. - printed p.15', verification_note='md-verified 2026-09-09 (§10.2 Problems and preventive measures concerning coloured and/or turbid samples, printed p.15-16) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.21 and 22. FINDING: the printed obligation is conditional ("In the case of highly coloured or turbid samples") and permissive ("may be taken"). Gate CR-025 requires colour_turbidity_correction == True unconditionally, so a clear sample fails - missing scope predicate - staged. The second sentence reproduces a printed typo ("should not to be mistaken"), which both the rendered page and the OCR carry.', verified_at=now() where id='72775c82-58f5-4e26-ae86-b9851184a1f2' and verification_status not in ('verified_against_standard','corrected');

-- degradation_type  (printed p.16)
update public.fields set verification_status='verified_against_standard', verification_quote='A distinction is made between: a) primary degradation by means of which the substance loses specific properties (identity, activity) and breaks down into simpler constituents; b) ultimate degradation, i.e. full degradation into thermodynamically stable inorganic products, e.g. carbon dioxide and water. This leads to the creation of new biomass in addition to carbon dioxide, water and mineral salts. - printed p.16', verification_note='md-verified 2026-09-09 (§11.1 Testing for biodegradation, printed p.16) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.22.', verified_at=now() where id='290955c6-1520-4253-970d-8b9e15c23f7a' and verification_status not in ('verified_against_standard','corrected');

-- degradation_test_method  (printed p.17)
update public.fields set verification_status='verified_against_standard', verification_quote='Biodegradation test methods can be classified in the following groups: a) Methods to measure ready biodegradability [...] b) Methods to determine potential (inherent) biodegradability. | Biodegradation can further be determined by: a) Simulation tests [...] b) Other methods [...] c) Measurements - printed p.17', verification_note='md-verified 2026-09-09 (§11.1 Testing for biodegradation, printed p.17) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.23. CAVEAT: the page prints FIVE groups across two lists; the enum encodes three (ready, inherent, simulation) and drops "Other methods" and "Measurements" - staged.', verified_at=now() where id='29648137-ca84-43f8-ab26-c1267c82f05c' and verification_status not in ('verified_against_standard','corrected');

-- c_1  (printed p.18)
update public.fields set verification_status='verified_against_standard', verification_quote='The criterion for bioaccumulation is the bioconcentration factor (BCF). It describes the quotients of the concentration in the organism (c1) and the concentration of the substance in the medium (e.g. water) or another parameter (e.g. food) (c2) at specific times or under steady-state conditions (BCFst). - printed p.18', verification_note='md-verified 2026-09-09 (§11.2 Testing for bioaccumulation, Eq. (1), printed p.18) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.24. FINDING: the page gives no units for c1 and c2, but §13.3 (printed p.24) requires "The BCF should be reported as a dimensionless figure", which forces c1 and c2 into the SAME unit. The encoding carries c_1 in mg/kg and c_2 in mg/l, so BCF = c_1/c_2 comes out in l/kg, not dimensionless - staged.', verified_at=now() where id='6d6cf383-a286-407c-94b4-07d97d653f43' and verification_status not in ('verified_against_standard','corrected');

-- c_2  (printed p.18)
update public.fields set verification_status='verified_against_standard', verification_quote='The criterion for bioaccumulation is the bioconcentration factor (BCF). It describes the quotients of the concentration in the organism (c1) and the concentration of the substance in the medium (e.g. water) or another parameter (e.g. food) (c2) at specific times or under steady-state conditions (BCFst). - printed p.18', verification_note='md-verified 2026-09-09 (§11.2 Testing for bioaccumulation, Eq. (1), printed p.18) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.24. See the c_1 note: unit basis mg/kg over mg/l contradicts the printed "dimensionless" requirement of §13.3 - staged.', verified_at=now() where id='9b4ab469-d840-457e-bf0c-8c4dd41ebd52' and verification_status not in ('verified_against_standard','corrected');

-- k_1  (printed p.18)
update public.fields set verification_status='verified_against_standard', verification_quote='BCF = c1/c2 = k1/k2 ... (1) | where k1 is the uptake rate; k2 is the elimination rate. - printed p.18', verification_note='md-verified 2026-09-09 (§11.2 Testing for bioaccumulation, Eq. (1), printed p.18) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.24. FINDING: the printed equation has two branches, c1/c2 AND k1/k2. Prod encodes only the c1/c2 branch (equation "BCF = c_1 / c_2"), so the field k_1 is an input to nothing - it feeds no equation and no gate. The page prints no unit for k1; the encoded "1/d" is an EKOWAI convention - staged.', verified_at=now() where id='f50c1af9-57f6-4bc9-8861-508dd0e24a0e' and verification_status not in ('verified_against_standard','corrected');

-- k_2  (printed p.18)
update public.fields set verification_status='verified_against_standard', verification_quote='BCF = c1/c2 = k1/k2 ... (1) | where k1 is the uptake rate; k2 is the elimination rate. - printed p.18', verification_note='md-verified 2026-09-09 (§11.2 Testing for bioaccumulation, Eqs. (1) and (2), printed p.18) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.24. The page prints no unit for k2; the encoded "1/d" (and the derived CT_50 unit "d") is an EKOWAI convention, consistent but unsourced - staged.', verified_at=now() where id='6665e5e9-8f1b-4f17-8995-e89bd59f55b1' and verification_status not in ('verified_against_standard','corrected');

-- BCF  (printed p.18)
update public.fields set verification_status='verified_against_standard', verification_quote='The criterion for bioaccumulation is the bioconcentration factor (BCF). [...] BCF = c1/c2 = k1/k2 ... (1) | A plateau or steady state has been achieved when three subsequent analyses at intervals of at least two days do not differ by ± 20 %. | The BCF should be reported as a dimensionless figure rounded to not more than three significant figures. - printed p.18', verification_note='md-verified 2026-09-09 (§11.2 (Eq. 1) and §13.3 Bioaccumulation tests (printed p.24, PDF p.30), printed p.18 and 24) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.24 and 30. FINDING: the printed steady-state criterion - three subsequent analyses at intervals of at least two days differing by no more than ± 20 % - is a hard numeric validity criterion with NO field and NO gate. The only gate on BCF is CR-026 "BCF >= 0", which a quotient of two concentrations can never violate: an effective no-op - staged.', verified_at=now() where id='821cf78f-9854-40fa-b15b-dccf45ff0b3a' and verification_status not in ('verified_against_standard','corrected');

-- CT_50  (printed p.18)
update public.fields set verification_status='verified_against_standard', verification_quote='If the elimination follows a one-compartment model of first order kinetics, it is possible to compute a CT50 value (clearance time for 50 % elimination) as follows: CT50 = loge2 / k2 ... (2) - printed p.18', verification_note='md-verified 2026-09-09 (§11.2 Testing for bioaccumulation, Eq. (2), printed p.18) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.24. FINDING: the page prints the numerator symbolically as loge2 (= ln 2). The encoded equation hard-codes 0.6931, a 4-decimal truncation of ln 2 = 0,693147..., which is nowhere printed. Gate CR-027 "CT_50 > 0" is an effective no-op (ln2/k2 is positive whenever k2 is) - staged.', verified_at=now() where id='83ae92f2-5062-4be5-a0e7-24cfcfd9ccb5' and verification_status not in ('verified_against_standard','corrected');

-- log_pow  (printed p.18)
update public.fields set verification_status='verified_against_standard', verification_quote='A preliminary estimation of the bioaccumulation potential is possible by means of the partition coefficient n-octanol water, log10 Pow, which is a measure for the lipophilic property of a substance [41]. In the range of log10 Pow 3 to 6, a relation of BCF = 0,1 Pow is often observed for fish. | The log10 Pow is not suitable to estimate the bioaccumulation potential in the case of ions (e.g. heavy metals); surfactants (underestimation); substances with molecular weights MW >700 [...]; highly lipophilic substances (log10 Pow >6) - printed p.18', verification_note='md-verified 2026-09-09 (§11.2 Testing for bioaccumulation, printed p.18) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.24. CAVEAT: the printed screening relation BCF = 0,1 Pow (valid for log10 Pow 3 to 6) is not encoded as an equation, and no gate carries the printed exclusions (ions, surfactants, MW >700, log10 Pow >6). log_pow is a field consumed by nothing.', verified_at=now() where id='75ef37a8-5c17-4ab3-ac09-1a422b2431c8' and verification_status not in ('verified_against_standard','corrected');

-- mutation_type  (printed p.19)
update public.fields set verification_status='verified_against_standard', verification_quote='Mutations are divided into three types. a) Gene mutations in which the base sequence in a gene is changed through the exchange of a DNA base (point mutation) or through the introduction or withdrawal of one or more DNA bases (changes in the reading code, frame shift mutations). b) Chromosome mutations in which the visible chromosome structure is changed, e.g. through deletion, translocation or inversion. c) Genome mutations in which the total chromosome quantity of cells is changed. - printed p.19', verification_note='md-verified 2026-09-09 (§11.3 Testing for genotoxicity, printed p.19) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.25. The printed list is explicitly closed ("divided into three types"), so the three-value enum is faithful.', verified_at=now() where id='d726926a-378a-4f0b-8cea-79f604be3af0' and verification_status not in ('verified_against_standard','corrected');

-- effect_concentration_metric  (printed p.20)
update public.fields set verification_status='verified_against_standard', verification_quote='It is customary to give concentrations as statistical parameters for the effect of a substance at which a specific quantum of action was observed (EC: effective concentration, ECx: x % effect). | For example, the EC50 gives the concentration at which the effect can be observed in 50 % of the test animals or 50 % effect (e.g. mortality, immobility) (mean effect concentration, 50 % quantile). | Toxicity tests mainly give the effective or threshold concentrations, e.g. NOEC/LOEC, EC10, EC50 and EC90 or LC (lethal concentration), respectively, where appropriate. - printed p.20', verification_note='md-verified 2026-09-09 (§12.3.1 General and §13.1 Toxicity tests (printed p.23, PDF p.29), printed p.20 and 23) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.26 and 29. CAVEAT: §13.1 prints several parameters reported TOGETHER ("NOEC/LOEC, EC10, EC50 and EC90"); the encoding is a single-select enum - single-select over a printed conjunction - staged.', verified_at=now() where id='fd16ecaf-14cf-4f18-96aa-bae652989651' and verification_status not in ('verified_against_standard','corrected');

-- statistical_method  (printed p.21)
update public.fields set verification_status='verified_against_standard', verification_quote='The classic estimation method for quantal variables of this kind is based on the maximum likelihood principle. In the case of normal distribution this leads to probit analysis [30], [31], with logistic distribution to logit analysis [32] and using the Weibull distribution to Weibit analysis [33]. | As a rule, the least-squares principle of linear and non-linear regression is used for the estimation methods. | In the case of normal distribution and variance homogeneity, statistical confirmation of the substance-specific effect is undertaken using simple variance analysis (ANOVA). NOEC and LOEC are determined using the Dunnett or Williams test [35]. - printed p.21', verification_note='md-verified 2026-09-09 (§12.3.2, §12.3.3, §12.3.4.3 (printed p.22, PDF p.28), printed p.21 and 22) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.27 and 28. CAVEAT: the page names the method "Weibit analysis" (using the Weibull distribution); the enum labels the value "weibull"/"Weibull analysis".', verified_at=now() where id='ef00644a-a77e-4652-89c6-f663ec051ac3' and verification_status not in ('verified_against_standard','corrected');

-- confidence_interval_reported  (printed p.22)
update public.fields set verification_status='verified_against_standard', verification_quote='The confidence interval can be calculated using the Fieller method [30], [36], [38]. | If the data situation is such that none of the above-mentioned methods can be applied, the EC50 and its confidence range can be approximated using alternative methods e.g. (Moving Average Method, Trimmed Sperman Kärber Method [30, 31] or simple interpolation (if necessary from EC0 and EC100). If EC100 is not obtained with undiluted samples, the maximum EC obtained should be reported. - printed p.22', verification_note='md-verified 2026-09-09 (§12.3.3 Metric (quantitative) variables, printed p.22) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.28.', verified_at=now() where id='c9c6e49b-7ccd-4d7c-8f5b-522301ae973e' and verification_status not in ('verified_against_standard','corrected');

-- biodegradation_degree  (printed p.23)
update public.fields set verification_status='verified_against_standard', verification_quote='The degree of degradation is described by the percentage decrease in concentration of one (or several) parameters as mentioned in 11.1. | The degradation kinetics (lag phase for adaptation, half-life time, ''10 days window'') should be described. | In such cases it is recommended to indicate the test result in a 10 %-range, e.g. biodegradation degree 70 % to 80 % DOC removal. - printed p.23', verification_note='md-verified 2026-09-09 (§13.2 Degradation tests and §12.3.3 (printed p.22, PDF p.28), printed p.23 and 22) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.29 and 28. CAVEAT: gate CR-033 (biodegradation_degree >= 0 AND <= 100) is a tautological domain check for a percentage, not a rule from the standard - an effective no-op. The printed rule that actually constrains the reported value (report in a 10 %-range) is not encoded - staged.', verified_at=now() where id='76a0aff5-8d3b-4625-9210-10e35f9e60bf' and verification_status not in ('verified_against_standard','corrected');

-- concentration_response_curve_presented  (printed p.23)
update public.fields set verification_status='verified_against_standard', verification_quote='Where possible, the concentration response curve should be presented together with the test results in a graph, e.g. as shown in figure 2, where the test results and ECx values are presented. This offers a clear picture of the character of the concentration response relationship and the agreement of the results in relation to the model. | The test criterion (''endpoint''), test organism, exposure time and, where possible, the confidence ranges, e.g. for the EC50, should also be given (see 12.3.4). - printed p.23', verification_note='md-verified 2026-09-09 (§13.1 Toxicity tests, printed p.23) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.29. CAVEAT: the printed obligation is qualified ("Where possible"); gate CR-032 requires concentration_response_curve_presented == True unconditionally - staged.', verified_at=now() where id='af4203e2-6412-42ec-aa96-c22bf9123bd6' and verification_status not in ('verified_against_standard','corrected');

-- test_report_complete  (printed p.24)
update public.fields set verification_status='verified_against_standard', verification_quote='The following data should be recorded in the test report: a) name of the laboratory performing the test; b) date and period of test; c) reference to the test method (International Standard number) used; d) test organism (e.g. scientific name, strain, source), therapeutic or acclimatory pretreatment (if any); e) designation of test material (batch number, origin, date and period of sampling); [...] j) evaluation method (logit, probit, graphical, computational); k) details of the test results; l) commentary on the test results, if necessary; m) signature of responsible investigator; n) signature of quality controller, if appropriate. - printed p.24', verification_note='md-verified 2026-09-09 (§14 Test report, printed p.24) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.30. FINDING: the printed modality is "should be recorded" - the whole reporting list is a recommendation. Three of its items (test_report_complete, test_method_reference, investigator_signature) are encoded is_required=true - staged.', verified_at=now() where id='59254f41-f566-4d94-a870-fdeaf1af755f' and verification_status not in ('verified_against_standard','corrected');

-- test_method_reference  (printed p.24)
update public.fields set verification_status='verified_against_standard', verification_quote='The following data should be recorded in the test report: [...] c) reference to the test method (International Standard number) used; - printed p.24', verification_note='md-verified 2026-09-09 (§14 c), printed p.24) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.30.', verified_at=now() where id='5c5d023b-5033-4722-b7ff-d107f6e3da16' and verification_status not in ('verified_against_standard','corrected');

-- investigator_signature  (printed p.24)
update public.fields set verification_status='verified_against_standard', verification_quote='The following data should be recorded in the test report: [...] m) signature of responsible investigator; - printed p.24', verification_note='md-verified 2026-09-09 (§14 m), printed p.24) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.30. Printed modality is "should"; the field is encoded is_required=true - staged.', verified_at=now() where id='d9e3b46d-392a-4010-acf0-38b8c33bc67f' and verification_status not in ('verified_against_standard','corrected');

-- quality_controller_signature  (printed p.24)
update public.fields set verification_status='verified_against_standard', verification_quote='The following data should be recorded in the test report: [...] n) signature of quality controller, if appropriate. - printed p.24', verification_note='md-verified 2026-09-09 (§14 n), printed p.24) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.30. The encoded is_required=false correctly mirrors the printed qualifier "if appropriate".', verified_at=now() where id='d1b82ef4-3d1f-4919-a3a5-bff88587adcd' and verification_status not in ('verified_against_standard','corrected');

-- qa_measures_documented  (printed p.25)
update public.fields set verification_status='verified_against_standard', verification_quote='The quality assurance of a test includes the planning of sampling, measurements and evaluation, documentation and assessment of the results and their recording. | The quality assurance measures can be subdivided into four sections: preparatory phase; internal quality control; external quality control audit; evaluation and documentation. | The complete documentation records and documents, all relevant data and information on the course of the examination, the results and the measures of analytical and statistical quality control should be stated. - printed p.25', verification_note='md-verified 2026-09-09 (§15.1 General and §15.6.4 Documentation (printed p.27, PDF p.33), printed p.25 and 27) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.31 and 33.', verified_at=now() where id='93ce404a-4ac8-4a93-9d92-9b5a2bb5f176' and verification_status not in ('verified_against_standard','corrected');

-- sop_documented  (printed p.26)
update public.fields set verification_status='verified_against_standard', verification_quote='It is essential that all parts of the test method used are described as they are actually used, which equipment and instruments are used and which quality assurance measures are taken. Frequently occurring steps, which are a routine part of all tests or of a specific test method, can be laid down in standard descriptions [standard operating procedures (SOPs)], which means that it is not necessary to mention them specifically in each test plan. - printed p.26', verification_note='md-verified 2026-09-09 (§15.4 Description of the test method, printed p.26) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.32. The printed modality is "It is essential that ... are described" - strong, but the SOP form itself is permissive ("can be laid down"). is_required=true rests on the "essential" clause, not on the SOP sentence.', verified_at=now() where id='df09997d-4094-44cb-b40f-35d6b6d1cbac' and verification_status not in ('verified_against_standard','corrected');

-- internal_qc_control_chart  (printed p.26)
update public.fields set verification_status='verified_against_standard', verification_quote='Internal quality control is an integral part of the overall test method. Normally, it is applied in those biological measurements which are conducted on a routine basis. It includes measures to identify, overcome and prevent errors, and should include the following steps: testing of actual preconditions in respect of staff, sampling, laboratory, equipment, test organisms, instruments and analytical methods; carrying out the calibration of instruments; carrying out tests with reference substances; keeping control charts; multiple determinations; plausibility control; validation. - printed p.26', verification_note='md-verified 2026-09-09 (§15.6.1 Internal quality control, printed p.26) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.32.', verified_at=now() where id='c7c34406-a8a1-4550-b6a7-59f2dbe035ed' and verification_status not in ('verified_against_standard','corrected');

-- ---- Section B: equations (2 rows) ----

-- equation 1
update public.equations set verification_status='verified_against_standard', verification_quote='The criterion for bioaccumulation is the bioconcentration factor (BCF). It describes the quotients of the concentration in the organism (c1) and the concentration of the substance in the medium (e.g. water) or another parameter (e.g. food) (c2) at specific times or under steady-state conditions (BCFst). | BCF = c1/c2 = k1/k2 ... (1) | where k1 is the uptake rate; k2 is the elimination rate. - printed p.18', verification_note='md-verified 2026-09-09 (§11.2 Testing for bioaccumulation, Eq. (1), printed p.18) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.24. The printed equation has TWO branches (c1/c2 and k1/k2); the encoded formula "BCF = c_1 / c_2" materializes only the first, leaving the encoded fields k_1/k_2 with no equation for the second branch.', verified_at=now() where id='786bb31e-ba90-4513-a97a-20af1deac310' and verification_status <> 'verified_against_standard';

-- equation 2
update public.equations set verification_status='verified_against_standard', verification_quote='If the elimination follows a one-compartment model of first order kinetics, it is possible to compute a CT50 value (clearance time for 50 % elimination) as follows: CT50 = loge2 / k2 ... (2) - printed p.18', verification_note='md-verified 2026-09-09 (§11.2 Testing for bioaccumulation, Eq. (2), printed p.18) [VA-OCR] - source is OCR of a scanned, text-layer-free PDF; this quote was RE-READ AND CONFIRMED on the rendered page image, PDF p.24. The printed numerator is the SYMBOL loge2 (= ln 2). The encoded formula "CT_50 = 0.6931 / k_2" substitutes a 4-decimal truncation of ln 2 = 0,693147...; that constant is nowhere printed in the standard.', verified_at=now() where id='415979e4-9949-4a6e-a54f-3b5da5e16fa9' and verification_status <> 'verified_against_standard';
